import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department with optional role filter.
    Intended for internal directory lookups."""
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')
    fields = request.args.get('fields', 'username,email,department')

    # Validate fields to prevent selecting sensitive columns
    allowed_fields = {'username', 'email', 'department', 'role', 'id'}
    requested_fields = [f.strip() for f in fields.split(',')]
    safe_fields = [f for f in requested_fields if f in allowed_fields]

    if not safe_fields:
        safe_fields = ['username', 'email', 'department']

    select_clause = ', '.join(safe_fields)

    # Build query with department filter
    if role_filter:
        query = f"SELECT {select_clause} FROM users WHERE department = '{department}' AND role = '{role_filter}'"
    else:
        query = f"SELECT {select_clause} FROM users WHERE department = '{department}'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        actor = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', actor, f'dept={department}')
        )
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID. API key is never returned."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
